'use strict';

// Read-only CDP screenshot helper. Never activates, reloads, focuses or clicks a page.
const crypto = require('node:crypto');
const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');

const PNG_SIGNATURE = Buffer.from('89504e470d0a1a0a', 'hex');
const MAX_PNG_BYTES = 8 * 1024 * 1024;
const MAX_TARGETS_RESPONSE_BYTES = 1024 * 1024;
const DEFAULT_PORT = 17447;

function checkedPort(value) {
  const port = Number(value);
  if (!Number.isInteger(port) || port < 1024 || port > 65535) {
    throw new Error('debug_port_invalid');
  }
  return port;
}

function scrubUrl(value) {
  try {
    const url = new URL(value);
    if (!['http:', 'https:'].includes(url.protocol)) return null;
    if (url.username || url.password) return null;
    return url.origin + url.pathname;
  } catch {
    return null;
  }
}

function checkedDebuggerUrl(value, port, id) {
  const ws = new URL(value);
  if (ws.protocol !== 'ws:' || !['localhost', '127.0.0.1', '[::1]'].includes(ws.hostname)
    || Number(ws.port) !== port || ws.username || ws.password
    || ws.search || ws.hash || ws.pathname !== '/devtools/page/' + id) {
    throw new Error('cdp_target_endpoint_rejected');
  }
  // Use Chrome's response for path identification, but never connect off localhost.
  return 'ws://127.0.0.1:' + port + ws.pathname;
}

async function readTargets(port, { fetchImpl = globalThis.fetch } = {}) {
  port = checkedPort(port);
  if (typeof fetchImpl !== 'function') throw new Error('fetch_unavailable');
  const response = await fetchImpl('http://127.0.0.1:' + port + '/json/list', {
    method: 'GET',
    redirect: 'error',
    signal: AbortSignal.timeout(4000),
  });
  if (!response.ok) throw new Error('cdp_discovery_failed');
  const body = await response.text();
  if (Buffer.byteLength(body, 'utf8') > MAX_TARGETS_RESPONSE_BYTES) {
    throw new Error('cdp_discovery_too_large');
  }
  let items;
  try { items = JSON.parse(body); } catch { throw new Error('cdp_discovery_invalid_json'); }
  if (!Array.isArray(items) || items.length > 500) throw new Error('cdp_discovery_invalid_targets');
  return items.filter(item => item && item.type === 'page'
    && typeof item.id === 'string' && /^[A-Za-z0-9_-]{1,128}$/.test(item.id)
    && scrubUrl(item.url) !== null
    && typeof item.webSocketDebuggerUrl === 'string');
}

async function listTabs(port = DEFAULT_PORT, options = {}) {
  const targets = await readTargets(port, options);
  return targets.map((item, index) => ({
    index,
    target_id: item.id,
    title: String(item.title || '').slice(0, 200),
    url: scrubUrl(item.url),
  }));
}

function inspectPng(data) {
  if (typeof data !== 'string' || data.length > Math.ceil(MAX_PNG_BYTES * 4 / 3) + 8
    || !/^[A-Za-z0-9+/]+={0,2}$/.test(data)) {
    throw new Error('cdp_screenshot_invalid_data');
  }
  const bytes = Buffer.from(data, 'base64');
  if (bytes.length < 24 || bytes.length > MAX_PNG_BYTES
    || !bytes.subarray(0, 8).equals(PNG_SIGNATURE)
    || bytes.toString('ascii', 12, 16) !== 'IHDR') {
    throw new Error('cdp_screenshot_invalid_png');
  }
  const width = bytes.readUInt32BE(16);
  const height = bytes.readUInt32BE(20);
  if (!width || !height || width > 16384 || height > 16384) {
    throw new Error('cdp_screenshot_invalid_dimensions');
  }
  return { bytes, width, height };
}

async function connectPage(url, { webSocketCtor = globalThis.WebSocket } = {}) {
  if (typeof webSocketCtor !== 'function') {
    throw new Error('websocket_unavailable_use_node_22_or_newer');
  }
  const socket = new webSocketCtor(url);
  let nextId = 1;
  const pending = new Map();
  let closed = false;
  let openResolve, openReject;
  const opened = new Promise((resolve, reject) => {
    openResolve = resolve;
    openReject = reject;
  });
  const connectionTimeout = setTimeout(() => openReject(new Error('cdp_connect_timeout')), 4000);
  socket.addEventListener('open', () => {
    clearTimeout(connectionTimeout);
    openResolve();
  }, { once: true });
  socket.addEventListener('error', () => {
    clearTimeout(connectionTimeout);
    openReject(new Error('cdp_socket_error'));
    for (const item of pending.values()) item.reject(new Error('cdp_socket_error'));
    pending.clear();
  });
  socket.addEventListener('close', () => {
    closed = true;
    clearTimeout(connectionTimeout);
    openReject(new Error('cdp_socket_closed'));
    for (const item of pending.values()) item.reject(new Error('cdp_socket_closed'));
    pending.clear();
  });
  socket.addEventListener('message', event => {
    let message;
    try { message = JSON.parse(typeof event.data === 'string' ? event.data : String(event.data)); }
    catch { return; }
    const item = pending.get(message.id);
    if (!item) return;
    pending.delete(message.id);
    if (message.error) item.reject(new Error('cdp_capture_failed'));
    else item.resolve(message.result);
  });
  try {
    await opened;
  } catch (error) {
    try { socket.close(); } catch {}
    throw error;
  }
  return {
    async send(method, params) {
      if (closed) throw new Error('cdp_socket_closed');
      const id = nextId++;
      return await new Promise((resolve, reject) => {
        const timeout = setTimeout(() => {
          pending.delete(id);
          reject(new Error('cdp_command_timeout'));
        }, 7000);
        pending.set(id, {
          resolve: value => { clearTimeout(timeout); resolve(value); },
          reject: error => { clearTimeout(timeout); reject(error); },
        });
        try {
          socket.send(JSON.stringify({ id, method, params }));
        } catch {
          clearTimeout(timeout);
          pending.delete(id);
          reject(new Error('cdp_send_failed'));
        }
      });
    },
    close() { try { socket.close(); } catch {} },
  };
}

async function captureTab({
  port = DEFAULT_PORT,
  targetId,
  expectedUrl = null,
  fetchImpl,
  connectImpl = connectPage,
} = {}) {
  port = checkedPort(port);
  if (typeof targetId !== 'string' || !/^[A-Za-z0-9_-]{1,128}$/.test(targetId)) {
    throw new Error('target_id_required');
  }
  const targets = await readTargets(port, { fetchImpl });
  const matches = targets.filter(target => target.id === targetId);
  if (matches.length !== 1) throw new Error('target_missing_or_ambiguous');
  const target = matches[0];
  const safeUrl = scrubUrl(target.url);
  if (expectedUrl !== null && expectedUrl !== safeUrl) {
    throw new Error('target_url_changed');
  }
  const wsUrl = checkedDebuggerUrl(target.webSocketDebuggerUrl, port, targetId);
  const cdp = await connectImpl(wsUrl);
  try {
    // Strictly read-only: no Page.bringToFront, Runtime.evaluate,
    // Emulation, Input, Target.activateTarget, scroll, or tab switching.
    const response = await cdp.send('Page.captureScreenshot', {
      format: 'png',
      fromSurface: true,
      captureBeyondViewport: false,
    });
    const { bytes, width, height } = inspectPng(response && response.data);
    return {
      target_id: targetId,
      url: safeUrl,
      bytes,
      width,
      height,
      sha256: crypto.createHash('sha256').update(bytes).digest('hex'),
    };
  } finally {
    cdp.close();
  }
}

function parseArgs(argv) {
  const args = {};
  for (const raw of argv) {
    if (raw === '--list') { args.list = true; continue; }
    const match = /^--(port|target-id|expect-url)=(.+)$/.exec(raw);
    if (!match || Object.hasOwn(args, match[1])) throw new Error('invalid_argument');
    args[match[1]] = match[2];
  }
  if (args.list && (args['target-id'] || args['expect-url'])) throw new Error('invalid_argument');
  if (!args.list && !args['target-id']) throw new Error('target_id_required');
  if (args['expect-url'] && !scrubUrl(args['expect-url'])) throw new Error('expected_url_invalid');
  return {
    list: !!args.list,
    port: checkedPort(args.port || DEFAULT_PORT),
    targetId: args['target-id'],
    expectedUrl: args['expect-url'] || null,
  };
}

async function main(argv) {
  const args = parseArgs(argv);
  if (args.list) {
    process.stdout.write(JSON.stringify({ tabs: await listTabs(args.port) }) + '\n');
    return;
  }
  const screenshot = await captureTab(args);
  // Private OS temporary directory. No arbitrary path writes or console base64.
  const directory = fs.mkdtempSync(path.join(os.tmpdir(), 'webbridge-cdp-'));
  const filePath = path.join(directory, 'tab.png');
  fs.writeFileSync(filePath, screenshot.bytes, { flag: 'wx', mode: 0o600 });
  const { bytes, ...metadata } = screenshot;
  process.stdout.write(JSON.stringify({
    ...metadata,
    mime_type: 'image/png',
    byte_length: bytes.length,
    image_path: filePath,
    activated_tab: false,
    focus_changed: false,
  }) + '\n');
}

if (require.main === module) {
  main(process.argv.slice(2)).catch(error => {
    process.stderr.write(JSON.stringify({ ok: false, error: error.message }) + '\n');
    process.exitCode = 1;
  });
}

module.exports = { DEFAULT_PORT, readTargets, listTabs, captureTab, inspectPng, checkedDebuggerUrl, parseArgs };

