const ONE_PIXEL = 'iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAusB9Y3rc0AAAAASUVORK5CYII=';
const port = 17447;
const targets = [
  {
    id: 'ABC_123', type: 'page', title: 'Background tab',
    url: 'https://example.org/view?q=secret#private',
    webSocketDebuggerUrl: 'ws://127.0.0.1:17447/devtools/page/ABC_123',
  },
  { id: 'extension', type: 'background_page', url: 'chrome-extension://abc/', webSocketDebuggerUrl: '' },
  { id: 'other', type: 'page', url: 'devtools://devtools/bundled', webSocketDebuggerUrl: '' },
];
const mockFetch = async (url, opts) => {
  assert.equal(url, 'http://127.0.0.1:17447/json/list');
  assert.equal(opts.redirect, 'error');
  return { ok: true, text: async () => JSON.stringify(targets) };
};

(async () => {
  const tabs = await listTabs(port, { fetchImpl: mockFetch });
  assert.deepEqual(tabs, [{
    index: 0, target_id: 'ABC_123', title: 'Background tab',
    url: 'https://example.org/view',
  }], 'only browser pages, without query tokens');

  const commands = [];
  let closed = 0;
  const mockConnect = async url => {
    assert.equal(url, 'ws://127.0.0.1:17447/devtools/page/ABC_123');
    return {
      async send(method, params) {
        commands.push({ method, params });
        return { data: ONE_PIXEL };
      },
      close() { closed++; },
    };
  };
  const capture = await captureTab({
    port, targetId: 'ABC_123', expectedUrl: 'https://example.org/view',
    fetchImpl: mockFetch, connectImpl: mockConnect,
  });
  assert.equal(capture.width, 1);
  assert.equal(capture.height, 1);
  assert.equal(capture.sha256.length, 64);
  assert.ok(Buffer.isBuffer(capture.bytes));
  assert.deepEqual(commands, [{
    method: 'Page.captureScreenshot',
    params: { format: 'png', fromSurface: true, captureBeyondViewport: false },
  }], 'MUST never activate/focus/scroll or mutate the background tab');
  assert.equal(closed, 1);

  await assert.rejects(() => captureTab({ port, targetId: 'missing',
    fetchImpl: mockFetch, connectImpl: mockConnect }), /target_missing_or_ambiguous/);
  await assert.rejects(() => captureTab({ port, targetId: 'ABC_123',
    expectedUrl: 'https://example.org/changed',
    fetchImpl: mockFetch, connectImpl: mockConnect }), /target_url_changed/);
  await assert.rejects(() => captureTab({ port, targetId: '../ABC_123',
    fetchImpl: mockFetch, connectImpl: mockConnect }), /target_id_required/);

  assert.throws(() => checkedDebuggerUrl(
    'ws://evil.test:17447/devtools/page/ABC_123', port, 'ABC_123'
  ), /rejected/);
  assert.throws(() => checkedDebuggerUrl(
    'ws://127.0.0.1:17448/devtools/page/ABC_123', port, 'ABC_123'
  ), /rejected/);
  assert.throws(() => checkedDebuggerUrl(
    'ws://127.0.0.1:17447/devtools/page/WRONG', port, 'ABC_123'
  ), /rejected/);
  assert.throws(() => checkedDebuggerUrl(
    'ws://127.0.0.1:17447/devtools/page/ABC_123?token=leak', port, 'ABC_123'
  ), /rejected/);

  assert.throws(() => inspectPng(Buffer.from('not png').toString('base64')), /invalid_png/);
  assert.throws(() => inspectPng('!invalid base64'), /invalid_data/);
  assert.deepEqual(parseArgs(['--list', '--port=17447']), {
    list: true, port, targetId: undefined, expectedUrl: null,
  });
  assert.deepEqual(parseArgs(['--target-id=ABC_123']), {
    list: false, port, targetId: 'ABC_123', expectedUrl: null,
  });
  assert.throws(() => parseArgs(['--target-id=ABC_123', '--list']), /invalid_argument/);
  assert.throws(() => parseArgs(['--port=80', '--list']), /debug_port_invalid/);

  const badDiscovery = async () => ({ ok: true, text: async () => '{broken' });
  await assert.rejects(() => readTargets(port, { fetchImpl: badDiscovery }), /invalid_json/);
  const failDiscovery = async () => ({ ok: false });
  await assert.rejects(() => readTargets(port, { fetchImpl: failDiscovery }), /discovery_failed/);

  const invalidResponse = await captureTab({
    port, targetId: 'ABC_123', fetchImpl: mockFetch,
    connectImpl: async () => ({ send: async () => ({ data: 'garbage' }), close() { closed++; } }),
  }).catch(error => error);
  assert.match(invalidResponse.message, /invalid_png/);
  assert.equal(closed, 2, 'CDP socket closed even on invalid screenshot');

  console.log('background tab capture safety tests passed');
})().catch(error => {
  console.error(error);
  process.exitCode = 1;
});

